UPDATE courses SET
    course_description = '<p>The UEE30820 Certificate III in Electrotechnology Electrician qualification is a pathway to a career in the electrotechnology sector. It will give students the required knowledge and practical exercises required by industry. This qualification allows graduates to apply for a NSW Electrician’s Licence. It covers electrical systems and equipment installation, testing, fault finding, repair, and maintenance of circuitry needed to apply for an Electrician licence. </p>',
    total_course_duration = '128 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <div class="width-90"> <h6 class="sec-headers">International Students</h6> <ul class="black-square"> <li>Students must be 18 years or above.</li> <li>Complete a Pre-Enrolment Review prior to enrolment</li> <li>Complete an online language, literacy and numeracy (LLN) assessment (on campus)</li> <li>Basic -intermediate level of computer skills</li> <li>Proficient in English International Students require either an <ul> <li>IELTS level of 5.5 or above with no band under 5.0 or</li> <li>TOEFL 62 (internet-based) or</li> <li>Pearson Test of English Academic (PTE) 46 or</li> <li>Cambridge English Advanced (CAE) score of 162 or</li> <li>OET score of C for each test component</li> </ul> </li> </ul> </div> </div> <div class="col-sm-6"> <h6 class="sec-headers">Domestic Students</h6> <ul class="black-square"> <li>18 years of age or older</li> <li>Satisfactorily completed Year 12 or equivalent </li> <li>Be able to read and comprehend course requirements</li> <li>Have an intermediate understanding of computers and the internet to assist with</li> <li>conducting research and complete assessments</li> </ul> </div> </div>',
    apply_form = 'https://ahsi.edu.au/uee30280-certificate-iii-in-electrotechnology-electrician/',
    updated_at = NOW()
WHERE cricos_course_code = '116822J';

UPDATE courses SET
    course_description = '<p>This qualification covers competencies to select, install, commission, fault find and maintain fire protection control systems in buildings. This qualification allows NSW approved Electricians to go to the next step in their career. It covers competencies to select, install, commission, fault find and maintain electrical systems and equipment with options, typically in explosion protection; electrical machines; electrical inspection; safety auditing; contracting; lifts and energy supply/distribution. </p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <div class="width-90"> <h6 class="sec-headers">International Students</h6> <ul class="black-square"> <li>Students must be 18 years or above.</li> <li>Students must have completed UEE30820 Cert III in Electrotechnology Electrician or have a current Unrestricted Electricians Licence or its equivalent issued in an Australian State or Territory</li> <li>Complete a Pre-Enrolment Review prior to enrolment</li> <li>Complete an online language, literacy and numeracy (LLN) assessment (on campus)</li> <li>Basic -intermediate level of computer skills</li> <li>Proficient in English International Students require either an <ul> <li>IELTS level of 5.5 or above with no band under 5.0 or</li> <li>TOEFL 62 (internet-based) or</li> <li>Pearson Test of English Academic (PTE) 46 or</li> <li>Cambridge English Advanced (CAE) score of 162 or</li> <li>OET score of C for each test component</li> </ul> </li> </ul> </div> </div> <div class="col-sm-6"> <h6 class="sec-headers">Domestic Students</h6> <ul class="black-square"> <li>18 years of age or older</li> <li>Students must have completed UEE30820 Cert III in Electrotechnology Electrician or have a current Unrestricted Electricians Licence or its equivalent issued in an Australian State or Territory</li> <li>Satisfactorily completed Year 12 or equivalent </li> <li>Be able to read and comprehend course requirements</li> <li>Have an intermediate understanding of computers and the internet to assist with</li> <li>conducting research and complete assessments</li> </ul> </div> </div>',
    apply_form = 'https://ahsi.edu.au/uee40620-certificate-iv-in-electrotechnology-electrician/',
    updated_at = NOW()
WHERE cricos_course_code = '116669B';

UPDATE courses SET
    course_description = '<p>This qualification covers competencies required to design and validate/evaluate electrical equipment and systems and provide technical advice/sales. Throughout the course students will build expertise in installing, testing and monitoring equipment and systems, solving problems and managing large electrical projects. The graduates will be able to work in the electrical industry. </p>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <div class="width-90"> <h6 class="sec-headers">International Students</h6> <ul class="black-square"> <li>Students must be 18 years or above.</li> <li>Complete a Pre-training Review prior to commencing training</li> <li>Complete an online language, literacy and numeracy (LLN) assessment (on campus)</li> <li>Basic -intermediate level of computer skills</li> <li>Successful completion of a Certificate III or above qualification in a related Engineering or Electrical pathway.</li> <li>Proficient in English International Students require either an <ul> <li>IELTS level of 5.5 or above with no band under 5.0 or</li> <li>TOEFL 62 (internet-based) or</li> <li>Pearson Test of English Academic (PTE) 46 or</li> <li>Cambridge English Advanced (CAE) score of 162 or</li> <li>OET score of C for each test component</li> </ul> </li> </ul> </div> </div> <div class="col-sm-6"> <h6 class="sec-headers">Domestic Students</h6> <ul class="black-square"> <li>18 years of age or older</li> <li> Successful completion of a Certificate III or above qualification in a related Engineering or Electrical pathway.</li> <li>Satisfactorily completed Year 12 or equivalent </li> <li>Be able to read and comprehend course requirements</li> <li>Have an intermediate understanding of computers and the internet to assist with</li> <li>conducting research and complete assessments</li> </ul> </div> </div>',
    apply_form = 'https://ahsi.edu.au/uee62122-advanced-diploma-of-engineering-technology-electrical-2/',
    updated_at = NOW()
WHERE cricos_course_code = '117011C';

UPDATE courses SET
    course_description = '<p>The CPC30220 – Certificate III in Carpentry qualification is a pathway to a career in the building sector. It will give graduates a trade outcome in carpentry, covering common skills for the construction industry including setting out, manufacturing, constructing, assembling, installing and repairing products made using timber and non-timber materials. </p>',
