UPDATE courses SET
    course_description = '<p>This qualification reflects the role of workers in a range of early childhood education settings who work within the requirements of the Education and Care Services National Regulations and the National Quality Standard. They support the implementation of an approved learning framework, and support children’s well being, learning and development. Depending on the setting, educators may work under direct supervision or autonomously.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
