    apply_form = 'https://ahsi.edu.au/chc30121-certificate-iii-in-early-childhood-education-and-care/',
    updated_at = NOW()
WHERE cricos_course_code = '111824C';

UPDATE courses SET
    course_description = '<p>This qualification reflects the role of workers in the community and/or residential settings. You may follow individualised plans to provide person-centred support to people in need due to ageing, disability or some other reason. You will also be able to work in nursing homes and short term accommodation facilities. Work involves using discretion and judgement in relation to individual support as well as taking responsibility for own outputs. Workers have a range of factual, technical and procedural knowledge, as well as some theoretical knowledge of the concepts and practices required to provide person-centred support.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-5 no-R-padding"> <img alt="" class="img-responsive img-100" src="https://ahsi.edu.au/wp-content/uploads/2019/09/course_blue_img.jpg"/> </div> <div class="col-sm-7"> <div class="course-blue-R"> <h3 class="sec-headers">Course Structure</h3> <p>This qualification consists of 15 units of competency and includes 9 core units and 6 elective units</p> <p>All students enrolled in this qualification are required to undertake work placement. Work placement provides the student with the opportunity to put into practice the skills learned in the classroom. Work placement requirements will be discussed during Student Orientation.</p> <p>AHSI will organise the work placement opportunities for students and where possible in organisations located close to their address. Should a student wish to change the work placement provider, they will need AHSI suitability approval and this can only take place after AHSI has assessed that organisation and signed a contract with the new provider.</p> <h3 class="sec-headers">Work placement requirements</h3> <ul> <li>Hold a Working with Children Certificate</li> <li>Hold a National Criminal Police Check</li> <li>Are physically, mentally and emotionally healthy to respond appropriately to personal needs</li> <li>First Aid Course certificate</li> <li>Up to date immunisation including COVID19</li> </ul> </div> </div> </div>',
    apply_form = 'https://ahsi.edu.au/chc33021-certificate-iii-in-individual-support/',
    updated_at = NOW()
WHERE cricos_course_code = '113484B';

UPDATE courses SET
    course_description = '<p>This qualification reflects the role of support workers who complete specialised tasks and functions in aged services; either in residential, home or community-based environments. To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency description.</p>',
    total_course_duration = '34 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-5 no-R-padding"> <img alt="" class="img-responsive img-100" src="https://ahsi.edu.au/wp-content/uploads/2019/09/course_blue_img.jpg"/> </div> <div class="col-sm-7"> <div class="course-blue-R"> <h3 class="sec-headers">Course Structure</h3> <p>This qualification consists of 18 units of competency that is made up of 15 core units and 3 elective units</p> <p>All students enrolled in this qualification are required to undertake work placement. Work placement provides the student with the opportunity to put into practice the skills learned in the classroom. Work placement requirements will be discussed during Student Orientation.</p> <p>AHSI will organise the work placement opportunities for students and where possible in organisations located close to their address. Should a student wish to change the work placement provider, they will need AHSI suitability approval and this can only take place after AHSI has assessed that organisation and signed a contract with the new provider.</p> <h3 class="sec-headers">Work placement requirements</h3> <ul> <li>Hold a Working with Children Check</li> <li>Hold a National Criminal Police Check</li> <li>Are physically, mentally and emotionally healthy to respond appropriately to personal needs</li> <li>First Aid Course certificate</li> <li>Up to date immunisation including COVID19</li> </ul> </div> </div> </div>',
    apply_form = 'https://ahsi.edu.au/chc43015-certificate-iv-in-ageing-support/',
    updated_at = NOW()
WHERE cricos_course_code = '103564G';

UPDATE courses SET
    course_description = '<p>This qualification reflects the role of workers who provide services to clients in relation to mental health issues. You will learn how to support people with mental health issues, explore trauma informed practice, liaise with other agencies involved in the patient-care approach, empower people through the recovery model and communicate effectively with clients and other services.</p>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-5 no-R-padding"> <img alt="" src="https://ahsi.edu.au/wp-content/uploads/2020/03/pn2ndr0g-1.jpg" style="width:100%;"/> </div> <div class="col-sm-7"> <div class="course-blue-R"> <h3 class="sec-headers">Course Structure</h3> <p>This qualification consists of 15 units of competency that is made up of 11 core units and 4 elective units</p> <p>All students enrolled in this qualification are required to undertake work placement. Work placement provides the student with the opportunity to put into practice the skills learned in the classroom. Work placement requirements will be discussed during Student Orientation.</p> <p>AHSI will organise the work placement opportunities for students and where possible in organisations located close to their address. Should a student wish to change the work placement provider, they will need AHSI suitability approval and this can only take place after AHSI has assessed that organisation and signed a contract with the new provider.</p> <h3 class="sec-headers">Work placement requirements</h3> <ul> <li>Hold a Working with Children Check</li> <li>Hold a National Criminal Police Check</li> <li>Are physically, mentally and emotionally healthy to respond appropriately to personal needs</li> <li>First Aid Course certificate</li> <li>Up to date immunisation including COVID19</li> </ul> </div> </div> </div>',
    apply_form = 'https://ahsi.edu.au/chc43315-certificate-iv-in-mental-health/',
    updated_at = NOW()
WHERE cricos_course_code = '108965E';

UPDATE courses SET
    course_description = '<p>This course will provide you with skills that will be extremely helpful in a variety of career pathways. If you are planning to embark on a career in counselling, are looking to improve your current career or want to further your own personal development our framework ensures you will be getting the most out your studies. As part of our counselling course you will become familiar with evidence-based counselling models, strategies and therapies as well as techniques from strength-based therapy.</p>',
