UPDATE courses SET
    course_description = '<p>This qualification reflects the role of workers who provide services to clients in relation to mental health issues. They can provide counselling, referral, advocacy and education/health promotion services. These workers are required to have high level specialist knowledge, skills and competencies especially regarding laws affecting people with mental health issues, the range of services available to them and health issues related to mental health.</p>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-5 no-R-padding"> <img alt="" src="https://ahsi.edu.au/wp-content/uploads/2020/03/pn2ndr0g-1.jpg" style="width:100%;"/> </div> <div class="col-sm-7"> <div class="course-blue-R"> <h3 class="sec-headers">Course Structure</h3> <p>This qualification consists of 20 units of competency that is made up of 15 core units and 5 elective units</p> <p>All students enrolled in this qualification are required to undertake work placement. Work placement provides the student with the opportunity to put into practice the skills learned in the classroom. Work placement requirements will be discussed during Student Orientation.</p> <p>AHSI will organise the work placement opportunities for students and where possible in organisations located close to their address. Should a student wish to change the work placement provider, they will need AHSI suitability approval and this can only take place after AHSI has assessed that organisation and signed a contract with the new provider.</p> <h3 class="sec-headers">Work placement requirements</h3> <ul> <li>Hold a Working with Children Check</li> <li>Hold a National Criminal Police Check</li> <li>Are physically, mentally and emotionally healthy to respond appropriately to personal needs</li> <li>First Aid Course certificate</li> <li>Up to date immunisation including COVID19</li> </ul> </div> </div> </div>',
    apply_form = 'https://ahsi.edu.au/chc53315-diploma-of-mental-health/',
    updated_at = NOW()
WHERE cricos_course_code = '';

UPDATE courses SET
    course_description = '<p>Cybersecurity has seen an increasing demand for skilled workers in every industry that uses computers, networks and the Internet. Cybersecurity experts work on measures to protect the data from theft, damage or ransomware when locked. The data can cover sensitive information, personally identifiable data (PII), health information, banking or other financial details, Intellectual property and government or industry information. </p>',
    total_course_duration = '4 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <div class="width-90"> <ul class="black-square"> <li>Must be 18 years of age or above</li> <li>Complete a Language, Literacy and Numeracy assessment prior to enrolment to assist with determining eligibility and to identify learning support needs</li> <li>Completed year 10 certificate or above</li> <li>Students should come with their own laptop or tablet</li> </ul> </div> </div> </div>',
    apply_form = 'https://ahsi.edu.au/bsbss00094-cyber-security-awareness-skill-set/',
    updated_at = NOW()
WHERE cricos_course_code = '';

UPDATE courses SET
    course_description = '<p>A Diploma in IT with a Cyber security specialisation will place you in a fast growing sector that lacks qualified workers. According to AustCyber, 51,309 dedicated workers last year worked in cyber security in Australia in 2023 but 12,500 jobs were vacant. The workforce needs to grow by 66 per cent to reach the 85,000 required by 2030, or just over 4800 jobs every year. This course will give a thorough understanding of IT, of Cyber security and how to meet business needs through IT solutions. Successful completion of this course will qualify you to work in IT and cyber security environments, will allow you to plan and implement complex IT networks, install virtual computing environments, gather and analyse threat information and protect critical infrastructure. .</p>',
    total_course_duration = '76 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <div class="width-90"> <h6 class="sec-headers">International Students</h6> <ul class="black-square"> <li>Students must be 18 years or above.</li> <li>Must meet Student Visa Requirements</li> <li>Complete a Pre-Enrolment Review prior to enrolment</li> <li>Complete an online language, literacy and numeracy (LLN) assessment (on campus)</li> <li>Basic -intermediate level of computer skills</li> <li>Completed education level of year 12 or equivalent</li> <li>Proficient in English International Students require either an <ul> <li>IELTS level of 6.0 or above with no band under 5.5 or</li> <li>TOEFL 60-78 (internet-based) or</li> <li>Pearson Test of English Academic (PTE) 52 or</li> <li>Cambridge English Advanced (CAE) score of 169 or</li> <li>OET score of C for each test component</li> </ul> </li> </ul> </div> </div> <div class="col-sm-6"> <h6 class="sec-headers">Domestic Students</h6> <ul class="black-square"> <li>18 years of age or older</li> <li>Satisfactorily completed Year 12 or equivalent </li> <li>Be able to read and comprehend course requirements</li> <li>Have an intermediate to advanced understanding of computers and the internet to assist with conducting research and complete assessments</li> </ul> </div> </div>',
    apply_form = 'https://ahsi.edu.au/ict50220-diploma-of-it-specialisation-cyber-security/',
    updated_at = NOW()
WHERE cricos_course_code = '116670J';

UPDATE courses SET
    course_description = '<p>An Advanced Diploma in IT with Telecommunications and Cyber security specialisations will take you to the next level after the Diploma of IT with Cyber security specialisation. According to AustCyber, 51,309 dedicated workers last year worked in cyber security in Australia in 2023 but 12,500 jobs were vacant. The workforce needs to grow by 66 per cent to reach the 85,000 required by 2030, or just over 4800 jobs every year. This course will advance your proficiency in IT, Cyber security and how to help businesses navigate the Cyber security threats and choice of solutions to be implemented. Successful completion of this course will qualify you to work in Telecommunications, IT and cyber security environments, will allow you to produce network designs, manage network traffic, monitor cyber alerts, threats and policies, implement best practices for identity management, for Cyber risk and evaluate the organisation’s compliance with legal obligations and security standards .</p>',
    total_course_duration = '76 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <div class="width-90"> <h6 class="sec-headers">International Students</h6> <ul class="black-square"> <li>Students must be 18 years or above.</li> <li>Must meet Student Visa Requirements</li> <li>Complete a Pre-Enrolment Review prior to enrolment</li> <li>Complete an online language, literacy and numeracy (LLN) assessment (on campus)</li> <li>Basic -intermediate level of computer skills</li> <li>Completed education level of year 12 or equivalent</li> <li>Proficient in English International Students require either an <ul> <li>IELTS level of 6.0 or above with no band under 5.5 or</li> <li>TOEFL 60-78 (internet-based) or</li> <li>Pearson Test of English Academic (PTE) 52 or</li> <li>Cambridge English Advanced (CAE) score of 169 or</li> <li>OET score of C for each test component</li> </ul> </li> </ul> </div> </div> <div class="col-sm-6"> <h6 class="sec-headers">Domestic Students</h6> <ul class="black-square"> <li>18 years of age or older</li> <li>Satisfactorily completed Year 12 or equivalent </li> <li>Be able to read and comprehend course requirements</li> <li>Have an intermediate to advanced understanding of computers and the internet to assist with conducting research and complete assessments</li> </ul> </div> </div>',
    apply_form = 'https://ahsi.edu.au/ict60220-advanced-diploma-of-it-specialisation-cyber-security/',
    updated_at = NOW()
WHERE cricos_course_code = '116671H';

UPDATE courses SET
    course_description = '<p>BSB80120 is the latest version of the Graduate Diploma of Management(Learning) approved by ASQA. This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others. </p>',
    total_course_duration = '128 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <div class="width-90"> <h6 class="sec-headers">International Students</h6> <ul class="black-square"> <li>Completed a Year 12 HSC or equivalent</li> <li>Must be 18 years of age or above</li> <li>Have intermediate computer skills</li> <li>Completed a bachelor’s degree in related fields of study<br/> <b>or</b><br/> Have completed a Diploma or Advanced Diploma qualification in related fields of study AND 1-year equivalent full-time relevant workplace experience </li> <li>Complete a Pre-Enrolment Review and Language, Literacy and Numeracy assessment</li> <li>Have a minimum IELTS score of 6.0 with no band below 5.5, or equivalent</li> </ul> </div> </div> <div class="col-sm-6"> <h6 class="sec-headers">Domestic Students</h6> <ul class="black-square"> <li>Completed a Year 12 HSC or equivalent</li> <li>Must be 18 years of age or above</li> <li>Have intermediate computer skills</li> <li>Completed a bachelor’s degree in related fields of study<br/> <b>or</b><br/> Have completed a Diploma or Advanced Diploma qualification in related fields of study AND 1-year equivalent full-time relevant workplace experience </li> <li>Complete a Pre-Enrolment Review and Language, Literacy and Numeracy assessment</li> </ul> </div> </div>',
    apply_form = 'https://ahsi.edu.au/bsb80120-graduate-diploma-of-management-learning/',
    updated_at = NOW()
WHERE cricos_course_code = '105526H';

UPDATE courses SET
    course_description = '<p>There is increased opportunity for new workers to pick up skills in direct care and progress to an entry level role. This skill set is for individuals who use introductory care practices to support fully qualified carers within an aged care or disability support environment.</p>',
    total_course_duration = '3 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <h3 class="sec-headers">Units of Study</h3> <table class="cdtable-2 table table-responsive" style="margin-bottom:5%;"> <tbody><tr> <td>CHCCCS015</td> <td>Provide individualised support</td> </tr> <tr> <td>HLTINF006</td> <td>Apply basic principles and practices of infection prevention and control</td> </tr> <tr> <td>HLTWHS002</td> <td>Follow safe work practices for direct client care</td> </tr> </tbody></table> </div> <div class="col-sm-6"> <div class="pad-l5"> <h3 class="sec-headers">Career opportunities</h3> <p style="margin-bottom:3%;">Possible career opportunities relevant to this qualification include:</p> <ul class="black-square"> <li>Aged care assistant</li> <li>Disability care assistant</li> </ul> <br/> </div> </div> <p></p> </div>',
    apply_form = 'https://ahsi.edu.au/chcss00114-entry-into-care-roles-skills-set/',
    updated_at = NOW()
WHERE cricos_course_code = '';

