UPDATE courses SET
    course_description = '<p>The General English course will help students build skills in reading, writing, speaking, listening and understanding other English speakers. The course will also help them learn to communicate in English in everyday scenarios, how to adapt to the Australian life and culture and also learn the words, phrases and core knowledge to be able to confidently continue a vocational course. It also offers a foundation for sitting IELTS tests. The course is for beginners, intermediate and advanced students. Classes will be offered across 5 levels: A1 beginner, A2 elementary, B1 pre-intermediate, B1+ intermediate, and B2 upper-intermediate. </p>',
    total_course_duration = '12 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="row"> <div class="col-sm-6"> <div class="width-90"> <h6 class="sec-headers">International Students</h6> <ul class="black-square"> <li>Completed a Year 12 HSC or equivalent</li> <li>Must be 18 years of age or above</li> <li>Have intermediate computer skills</li> <li>Complete a Pre-Enrolment Review and Language, Literacy and Numeracy assessment to allow AHSI to ascertain the student’s level</li> <li>There is no minimum IELTS score</li> </ul> </div> </div> <div class="col-sm-6"> <h6 class="sec-headers">Domestic Students</h6> <ul class="black-square"> <li>This course does not apply to domestic students</li> </ul> </div> </div>',
    apply_form = 'https://ahsi.edu.au/elicos-english-courses/',
    updated_at = NOW()
WHERE cricos_course_code = '117206C';